/**
 * Engine regressions for the German and Australian calculators on the migration 0037 snapshots (fixtures generated by applying
 * the migration to a scratch Postgres and exporting the rows), plus install periods, input parsing and display helpers.
 * UK and US regressions live in uk.test.ts / the calc golden tests and are untouched.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { calculateGlobal } from '../calc/calculate-global';
import type { GlobalCalcSuccess } from '../calc/global-types';
import { createGlobalRepo } from '../db/repo-global';
import de from './__fixtures__/de-0037.json';
import au from './__fixtures__/au-0037.json';
import { AU_STRINGS } from './intl-strings';
import { loadCalculatorPageData } from './uk-page-data';
import { buildUkContext, exportOffers, installPeriodsFor, orientationFactor, runSources, scaleProduction, type UkCalculatorProps } from './uk';

type Tables = Record<string, Record<string, unknown>[]>;
const fakeRepo = (t: Tables) =>
  createGlobalRepo({
    env: { url: 'https://fixture.supabase.co/', key: 'sb_publishable_FIXTUREKEY' },
    fetch: (async (input: RequestInfo | URL) => {
      const u = new URL(String(input));
      let rows = t[u.pathname.replace('/rest/v1/', '')] ?? [];
      for (const [k, v] of u.searchParams) {
        if (['select', 'order', 'limit'].includes(k)) continue;
        rows = rows.filter((r) => String(r[k]) === v.slice(3));
      }
      return new Response(JSON.stringify(rows), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }) as unknown as typeof fetch,
  });

const load = async (country: 'DE' | 'AU', t: unknown, today = '2026-11-22'): Promise<UkCalculatorProps> => {
  const d = await loadCalculatorPageData(country, today, fakeRepo(t as Tables));
  if (!d.ok) throw new Error(`load ${country}: ${d.error.message} ${d.error.issues ?? ''}`);
  return d.props;
};

// PVGIS 5.3 PVcalc, 1 kWp, loss 14, optimal tilt, equator-facing (research packs places_yield.csv, retrieved 2026-11-22)
const MUENCHEN = { annualKwhPerKw: 1140.7, monthlyKwhPerKw: [52.0, 72.5, 104.4, 119.9, 120.1, 124.1, 128.3, 122.5, 106.5, 85.9, 55.2, 49.4] };
const DUESSELDORF = { annualKwhPerKw: 1035.2, monthlyKwhPerKw: [37.9, 56.1, 92.8, 117.2, 125.2, 123.5, 121.8, 113.7, 99.0, 73.0, 44.3, 30.9] };
const SYDNEY = { annualKwhPerKw: 1559.5, monthlyKwhPerKw: [139.2, 123.8, 129.5, 121.9, 119.1, 98.4, 117.4, 135.0, 145.7, 148.0, 138.8, 143.0] };
const BRISBANE = { annualKwhPerKw: 1534.6, monthlyKwhPerKw: [128.7, 117.8, 126.2, 125.8, 121.1, 106.9, 120.9, 138.7, 140.2, 141.3, 135.0, 132.0] };
const PERTH = { annualKwhPerKw: 1671.6, monthlyKwhPerKw: [171.1, 154.3, 157.0, 131.5, 117.3, 98.7, 98.9, 118.4, 133.3, 158.0, 162.6, 170.6] };

function run(p: UkCalculatorProps, a: { utility: string; offer: string; bill: number; battery: 0 | 1; date: string; production: typeof MUENCHEN }): GlobalCalcSuccess {
  const ctx = buildUkContext(p, { utilityId: a.utility, exportPolicyId: a.offer }, a.production);
  if (!ctx) throw new Error('context');
  const r = calculateGlobal({ utilityId: a.utility, avgMonthlyBill: a.bill, battery: a.battery, shading: 'none', installDate: a.date }, ctx);
  if (!r.ok) throw new Error(`calc failed: ${r.reason} ${(r.missing ?? []).join(', ')}`);
  return r;
}
const summary = (r: GlobalCalcSuccess) => ({
  usage: r.annualUsageKwh,
  size: r.size,
  cost: r.cost,
  incentive: r.upfrontIncentive,
  year1: r.year1Savings,
  payback: r.paybackYears,
  net: r.netSavings25,
});

describe('Germany (migration 0037)', () => {
  it('loads: 16 Bundesländer, two EEG offers, 0% VAT, 20-year horizon, install horizon 31 Dec 2026', async () => {
    const p = await load('DE', de);
    expect(p.utilities).toHaveLength(16);
    expect(p.utilities.every((u) => u.avg_rate_per_kwh?.likely === 0.3618 && u.fixed_monthly_charge === 0)).toBe(true);
    expect(p.exportPolicies.map((x) => x.id).sort()).toEqual(['de-eeg-teileinspeisung', 'de-eeg-volleinspeisung']);
    expect(p.vatRates.map((v) => [v.applies_to, v.rate])).toEqual([['battery', 0], ['solar', 0]]);
    expect(p.assumptions.analysis_years.value).toBe(20);
    expect(p.assumptions.install_horizon?.until).toBe('2026-12-31');
    expect(p.locations).toHaveLength(16);
  });

  it('offers only the install period the sourced EEG rates cover, with the rates in cents', async () => {
    const p = await load('DE', de);
    const periods = installPeriodsFor(p);
    expect(periods.map((x) => [x.startsOn, x.endsOn, x.solarVat])).toEqual([['2026-11-22', '2026-12-31', 0]]);
    expect(exportOffers(p.exportPolicies, '2026-11-22').map((o) => [o.id, o.pence])).toEqual([
      ['de-eeg-teileinspeisung', 7.7],
      ['de-eeg-volleinspeisung', 12.22],
    ]);
    // After the rates end there is no rate and the calculator never invents one.
    expect(exportOffers(p.exportPolicies, '2027-01-15').map((o) => o.pence)).toEqual([null, null]);
    const ctx = buildUkContext(p, { utilityId: 'de-bayern', exportPolicyId: 'de-eeg-teileinspeisung' }, MUENCHEN)!;
    const r = calculateGlobal({ utilityId: 'de-bayern', avgMonthlyBill: 110, battery: 0, shading: 'none', installDate: '2027-01-15' }, ctx);
    expect(r.ok).toBe(false);
  });

  it('scenario 1: Bayern, EUR 110 a month, no battery, surplus feed-in (Teileinspeisung)', async () => {
    const r = run(await load('DE', de), { utility: 'de-bayern', offer: 'de-eeg-teileinspeisung', bill: 110, battery: 0, date: '2026-11-22', production: MUENCHEN });
    expect(summary(r)).toMatchInlineSnapshot(`
      {
        "cost": {
          "high": 6700,
          "likely": 4900,
          "low": 3600,
        },
        "incentive": {
          "high": 0,
          "likely": 0,
          "low": 0,
        },
        "net": {
          "high": 16550,
          "likely": 8950,
          "low": 4150,
        },
        "payback": {
          "high": 11.5,
          "likely": 7.5,
          "low": 5,
        },
        "size": {
          "high": 3.2,
          "likely": 2.9,
          "low": 2.6,
        },
        "usage": 3600,
        "year1": {
          "high": 850,
          "likely": 650,
          "low": 450,
        },
      }
    `);
  });

  it('scenario 2: Nordrhein-Westfalen, EUR 80 a month, with a 10 kWh battery, surplus feed-in', async () => {
    const r = run(await load('DE', de), { utility: 'de-nordrhein-westfalen', offer: 'de-eeg-teileinspeisung', bill: 80, battery: 1, date: '2026-12-01', production: DUESSELDORF });
    expect(summary(r)).toMatchInlineSnapshot(`
      {
        "cost": {
          "high": 10450,
          "likely": 8050,
          "low": 6500,
        },
        "incentive": {
          "high": 0,
          "likely": 0,
          "low": 0,
        },
        "net": {
          "high": 14400,
          "likely": 7000,
          "low": 700,
        },
        "payback": {
          "high": 18.5,
          "likely": 11.5,
          "low": 8,
        },
        "size": {
          "high": 2.6,
          "likely": 2.3,
          "low": 2.1,
        },
        "usage": 2700,
        "year1": {
          "high": 850,
          "likely": 650,
          "low": 500,
        },
      }
    `);
  });

  it('scenario 3: Bayern, EUR 110 a month, full feed-in (Volleinspeisung): the bill does not fall, the income is the payback', async () => {
    const p = await load('DE', de);
    const full = run(p, { utility: 'de-bayern', offer: 'de-eeg-volleinspeisung', bill: 110, battery: 0, date: '2026-11-22', production: MUENCHEN });
    expect(summary(full)).toMatchInlineSnapshot(`
      {
        "cost": {
          "high": 6700,
          "likely": 4900,
          "low": 3600,
        },
        "incentive": {
          "high": 0,
          "likely": 0,
          "low": 0,
        },
        "net": {
          "high": 3600,
          "likely": 2750,
          "low": 1650,
        },
        "payback": {
          "high": 15.5,
          "likely": 12.5,
          "low": 10.5,
        },
        "size": {
          "high": 3.2,
          "likely": 2.9,
          "low": 2.6,
        },
        "usage": 3600,
        "year1": {
          "high": 450,
          "likely": 400,
          "low": 350,
        },
      }
    `);
    // income = size x yield x 12.22 ct held flat: year-1 likely within a euro of that
    const expected = full.size.likely * MUENCHEN.annualKwhPerKw * 0.1222;
    expect(Math.abs(full.year1Savings.likely - expected)).toBeLessThan(75);
  });

  it('orientation factors come from the data and sources list the Verbraucherzentrale, UStG and Eurostat rows', async () => {
    const p = await load('DE', de);
    expect(orientationFactor(p.assumptions, 'south')).toBe(1);
    expect(orientationFactor(p.assumptions, 'east_west')).toBe(0.786);
    expect(orientationFactor(p.assumptions, 'north')).toBe(0.514);
    const urls = runSources(p, { utilityId: 'de-bayern', exportPolicyId: 'de-eeg-teileinspeisung' }, '2026-11-22', 1).map((s) => s.url);
    expect(urls.some((u) => u.includes('eurostat'))).toBe(true);
    expect(urls.some((u) => u.includes('bundesnetzagentur'))).toBe(true);
    expect(urls.some((u) => u.includes('verbraucherzentrale'))).toBe(true);
    expect(urls.some((u) => u.includes('ustg_1980'))).toBe(true);
    expect(scaleProduction(MUENCHEN, 0.786).annualKwhPerKw).toBeCloseTo(896.6, 1);
  });
});

describe('Australia (migration 0037)', () => {
  it('loads: 7 networks, 6 feed-in offers, 2 dated battery rebate rows, no VAT table, install horizon 30 Jun 2027', async () => {
    const p = await load('AU', au);
    expect(p.utilities).toHaveLength(7);
    expect(p.exportPolicies).toHaveLength(6);
    expect(p.incentives).toHaveLength(2);
    expect(p.vatRates).toHaveLength(0);
    expect(p.assumptions.install_horizon?.until).toBe('2027-06-30');
    const ausgrid = p.utilities.find((u) => u.id === 'au-ausgrid')!;
    expect(ausgrid.avg_rate_per_kwh?.likely).toBe(0.331372);
    expect(ausgrid.fixed_monthly_charge).toBe(50.56);
  });

  it('splits installs at the 1 Jan 2027 rebate step-down and shows the per-kWh rebate of each period', async () => {
    const p = await load('AU', au);
    expect(installPeriodsFor(p).map((x) => [x.startsOn, x.endsOn, x.batteryRebatePerKwh])).toEqual([
      ['2026-11-22', '2026-12-31', 269.42],
      ['2027-01-01', '2027-06-30', 225.83],
    ]);
    // After the horizon passes nothing is offered.
    expect(installPeriodsFor({ ...p, today: '2027-07-02' })).toEqual([]);
  });

  it('feed-in offers: a range with a derived midpoint, regulated rates and the Victorian zero floor', async () => {
    const p = await load('AU', au);
    const by = Object.fromEntries(exportOffers(p.exportPolicies, '2026-11-22').map((o) => [o.id, o.pence]));
    expect(by).toEqual({
      'au-nsw-ipart-benchmark': 4.95,
      'au-nt-jacana-anytime': 9.33,
      'au-qld-regional-qca': 6.01,
      'au-tas-aurora-regulated': 9.28,
      'au-vic-minimum': 0,
      'au-wa-synergy-debs': 2,
    });
    // 2027-28 regulated rates are not published: only the open-ended offers keep a rate after 30 Jun 2027.
    const later = exportOffers(p.exportPolicies, '2027-07-15').filter((o) => o.pence !== null).map((o) => o.id);
    expect(later.sort()).toEqual(['au-vic-minimum', 'au-wa-synergy-debs']);
  });

  it('scenario 1: Ausgrid (Sydney), AUD 200 a month, no battery, IPART benchmark', async () => {
    const r = run(await load('AU', au), { utility: 'au-ausgrid', offer: 'au-nsw-ipart-benchmark', bill: 200, battery: 0, date: '2026-11-22', production: SYDNEY });
    expect(summary(r)).toMatchInlineSnapshot(`
      {
        "cost": {
          "high": 5200,
          "likely": 3100,
          "low": 2500,
        },
        "incentive": {
          "high": 0,
          "likely": 0,
          "low": 0,
        },
        "net": {
          "high": 35050,
          "likely": 19650,
          "low": 9450,
        },
        "payback": {
          "high": 8,
          "likely": 4,
          "low": 2.5,
        },
        "size": {
          "high": 3.5,
          "likely": 3.1,
          "low": 2.8,
        },
        "usage": 5400,
        "year1": {
          "high": 1150,
          "likely": 800,
          "low": 550,
        },
      }
    `);
    expect(r.incentivesApplied).toEqual([]);
  });

  it('scenario 2: Energex (Brisbane), AUD 180 a month, with a battery installed in December 2026 (factor 6.8)', async () => {
    const r = run(await load('AU', au), { utility: 'au-energex', offer: 'au-qld-regional-qca', bill: 180, battery: 1, date: '2026-12-15', production: BRISBANE });
    expect(summary(r)).toMatchInlineSnapshot(`
      {
        "cost": {
          "high": 18800,
          "likely": 14800,
          "low": 12150,
        },
        "incentive": {
          "high": 2700,
          "likely": 2700,
          "low": 2400,
        },
        "net": {
          "high": 34600,
          "likely": 17500,
          "low": 4100,
        },
        "payback": {
          "high": 19.5,
          "likely": 11,
          "low": 7.5,
        },
        "size": {
          "high": 3.4,
          "likely": 3.1,
          "low": 2.7,
        },
        "usage": 5200,
        "year1": {
          "high": 1300,
          "likely": 1000,
          "low": 750,
        },
      }
    `);
    expect(r.incentivesApplied.map((i) => i.id)).toEqual(['au-chbp-2026-05-to-12']);
  });

  it('scenario 3: the same battery installed in January 2027 (factor 5.7) gets a smaller rebate and a higher net cost', async () => {
    const p = await load('AU', au);
    const a = run(p, { utility: 'au-energex', offer: 'au-qld-regional-qca', bill: 180, battery: 1, date: '2026-12-15', production: BRISBANE });
    const b = run(p, { utility: 'au-energex', offer: 'au-qld-regional-qca', bill: 180, battery: 1, date: '2027-01-15', production: BRISBANE });
    expect(summary(b)).toMatchInlineSnapshot(`
      {
        "cost": {
          "high": 18800,
          "likely": 14800,
          "low": 12150,
        },
        "incentive": {
          "high": 2300,
          "likely": 2250,
          "low": 2050,
        },
        "net": {
          "high": 34150,
          "likely": 17050,
          "low": 3750,
        },
        "payback": {
          "high": 20,
          "likely": 11.5,
          "low": 8,
        },
        "size": {
          "high": 3.4,
          "likely": 3.1,
          "low": 2.7,
        },
        "usage": 5200,
        "year1": {
          "high": 1300,
          "likely": 1000,
          "low": 750,
        },
      }
    `);
    expect(b.incentivesApplied.map((i) => i.id)).toEqual(['au-chbp-2027-01-to-06']);
    // rebate on 10 kWh: 10 x 269.42 = 2,694 (likely) before, 10 x 225.83 = 2,258 after (rounded to the nearest AUD 50)
    expect(a.upfrontIncentive.likely).toBe(2700);
    expect(b.upfrontIncentive.likely).toBe(2250);
    expect(b.paybackYears.likely!).toBeGreaterThan(a.paybackYears.likely!);
  });

  it('Western Australia (Synergy A1, DEBS 2 c) runs with the WA flat tariff', async () => {
    const r = run(await load('AU', au), { utility: 'au-synergy-a1', offer: 'au-wa-synergy-debs', bill: 220, battery: 0, date: '2026-11-22', production: PERTH });
    expect(r.ok).toBe(true);
    expect(r.size.likely).toBeGreaterThan(1.5);
  });

  it('the rebate and cost sources are listed, the cost rows say SECONDARY, and the pole-facing factor is stored under "north"', async () => {
    const p = await load('AU', au);
    const labels = runSources(p, { utilityId: 'au-energex', exportPolicyId: 'au-qld-regional-qca' }, '2026-12-15', 1, AU_STRINGS.sources).map((s) => s.label);
    expect(labels.some((l) => l.startsWith('Rebate: Cheaper Home Batteries Program'))).toBe(true);
    expect(labels).toContain('Installed solar cost (SolarQuotes, secondary source)');
    expect(p.costs.installed_cost_per_watt.line.note).toMatch(/^SECONDARY SOURCE/);
    expect(p.costs.battery_installed_cost.line.note).toMatch(/^SECONDARY SOURCE/);
    expect(orientationFactor(p.assumptions, 'north')).toBe(0.528);
  });
});

describe('migration 0037 text matches the fixtures', () => {
  const sql = readFileSync('supabase/migrations/0037_de_au_calculator.sql', 'utf8');
  it('holds the key sourced values the fixtures were generated from', () => {
    for (const needle of [
      "'DE', 'DE', 'installed_cost_per_watt', 1.41, 1.71, 2.09",
      "'DE', 'DE', 'battery_installed_cost', 3600, 4100, 5100",
      "'de-eeg-teileinspeisung', '2026-08-01', '2026-12-31', 1, null, 0.077, 0.077, 0.077",
      "'de-eeg-volleinspeisung', '2026-08-01', '2026-12-31', 1, null, 0.1222, 0.1222, 0.1222",
      "'AU', 'AU', 'installed_cost_per_watt', 0.9, 1, 1.5",
      "'AU', 'AU', 'battery_installed_cost', 9720, 11720, 13720",
      'round(39.62 * 6.8, 2), round(40 * 6.8, 2)',
      'round(39.62 * 5.7, 2), round(40 * 5.7, 2)',
      "'au-nsw-ipart-benchmark', '2026-07-01', '2027-06-30', 1, null, 0.034, 0.0495, 0.065",
    ]) expect(sql).toContain(needle);
    expect(sql).not.toMatch(/25D/);
  });
});
